INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4481991, 645990, 3214, '<td valign="top">Panning but obstructed by the motion blur.  The heavy frame is overbearing, and emphasizes the tight crop at the bottom.  Wonder if you''ve got a free study from that shoot?  :-)</td>', 'Panning but obstructed by the motion blur.  The heavy frame is overbearing, and emphasizes the tight crop at the bottom.  Wonder if you''ve got a free study from that shoot?  :-)', '2008-02-13 00:19:07.000000', NULL, 1),
(4482024, 646262, 74953, '<td valign="top">Nice capture of the bird in flight, but I don''t get any sense of panning.</td>', 'Nice capture of the bird in flight, but I don''t get any sense of panning.', '2008-02-13 00:26:31.000000', NULL, 1),
(4482026, 645811, 3214, '<td valign="top">A pano crop would keep the attention on your subject.  I like how he''s got his neck stuck out, emphasizing the speed.  Nice background on the top, too.</td>', 'A pano crop would keep the attention on your subject.  I like how he''s got his neck stuck out, emphasizing the speed.  Nice background on the top, too.', '2008-02-13 00:27:11.000000', NULL, 1),
(4482028, 646458, 74953, '<td valign="top">The image is out of focus and hard to tell what the subject is.</td>', 'The image is out of focus and hard to tell what the subject is.', '2008-02-13 00:27:37.000000', NULL, 1),
(4482083, 644303, 51518, '<td valign="top">wow......great shot</td>', 'wow......great shot', '2008-02-13 00:39:29.000000', NULL, 1),
(4482104, 645700, 77838, '<td valign="top">The shot seems so simple, yet I have to wonder...?  Is this just a self-portrait while you spun in your desk chair?!  A genius is what this shot is!  This technique never even entered my mind.<br/> <br/>"Use the technique of panning to create an effective photograph"; and this is exactly what you did.  Way to think outside the box. I like it. -Brandon<br/> <br/>The background could''ve been blurred a little more for me but this concept is great.</td>', 'The shot seems so simple, yet I have to wonder...?  Is this just a self-portrait while you spun in your desk chair?!  A genius is what this shot is!  This technique never even entered my mind. "Use the technique of panning to create an effective photograph"; and this is exactly what you did.  Way to think outside the box. I like it. -Brandon The background could''ve been blurred a little more for me but this concept is great.', '2008-02-13 00:45:03.000000', NULL, 1),
(4482112, 644248, 3214, '<td valign="top">Wins the humor vote!</td>', 'Wins the humor vote!', '2008-02-13 00:46:23.000000', NULL, 1),
(4482118, 646473, 74953, '<td valign="top">I would consider this more a long exposure than a panning shot.</td>', 'I would consider this more a long exposure than a panning shot.', '2008-02-13 00:47:23.000000', NULL, 1),
(4482121, 646358, 77838, '<td valign="top">I wish the subject was able to be seen so that we could connect the title with the photo.  I would''ve liked to have something for my eye to end up on after following the "rail".</td>', 'I wish the subject was able to be seen so that we could connect the title with the photo.  I would''ve liked to have something for my eye to end up on after following the "rail".', '2008-02-13 00:48:07.000000', NULL, 1),
(4482124, 643642, 77838, '<td valign="top">There''s not alot of "panning" in this picture.  Unless you''re trying for the sun?</td>', 'There''s not alot of "panning" in this picture.  Unless you''re trying for the sun?', '2008-02-13 00:49:01.000000', NULL, 1),
(4482125, 646379, 74953, '<td valign="top">Unless I''m missing something, I don''t see any panning in this shot.</td>', 'Unless I''m missing something, I don''t see any panning in this shot.', '2008-02-13 00:49:42.000000', NULL, 1),
(4482129, 646267, 77838, '<td valign="top">I love the happy expression on her face here.  A kid in her prime. -BB</td>', 'I love the happy expression on her face here.  A kid in her prime. -BB', '2008-02-13 00:50:45.000000', NULL, 1),
(4482137, 644793, 77838, '<td valign="top">Awesome, plain genius here, with the play on words!  At least your pan is clean and shiny; AND it''s in focus.  Nice shot. -BB</td>', 'Awesome, plain genius here, with the play on words!  At least your pan is clean and shiny; AND it''s in focus.  Nice shot. -BB', '2008-02-13 00:54:33.000000', NULL, 1),
(4482196, 646336, 39675, '<td valign="top">Amazing how sharp you were able to get the can.  Its a perfect exposure too.</td>', 'Amazing how sharp you were able to get the can.  Its a perfect exposure too.', '2008-02-13 01:20:52.000000', NULL, 1),
(4482203, 646356, 39675, '<td valign="top">I like it.  I can tell you put so much thought and planning into this photo.  You must love birds!</td>', 'I like it.  I can tell you put so much thought and planning into this photo.  You must love birds!', '2008-02-13 01:22:57.000000', NULL, 1),
