(4485385, 644363, 64989, '<td valign="top">This is just awesome to me!  I think you did a good job on the technicals of the challenge, and the speeding granny just cracks me up!</td>', 'This is just awesome to me!  I think you did a good job on the technicals of the challenge, and the speeding granny just cracks me up!', '2008-02-13 22:53:52.000000', NULL, 1),
(4485417, 646379, 84150, '<td valign="top">Sorry, but I don''t see panning in this image...</td>', 'Sorry, but I don''t see panning in this image...', '2008-02-13 23:02:25.000000', NULL, 1),
(4485469, 644363, 47091, '<td valign="top">Love it</td>', 'Love it', '2008-02-13 23:27:19.000000', NULL, 1),
(4485474, 646473, 47091, '<td valign="top">I don''t think this is panning</td>', 'I don''t think this is panning', '2008-02-13 23:31:36.000000', NULL, 1),
(4485477, 644463, 47091, '<td valign="top">The person looks out of focus to me</td>', 'The person looks out of focus to me', '2008-02-13 23:32:58.000000', NULL, 1),
(4485492, 646470, 57775, '<td valign="top">Great shot!</td>', 'Great shot!', '2008-02-13 23:39:53.000000', NULL, 1),
(4485508, 646458, 65319, '<td valign="top">I''m fascinated by this photo somehow!</td>', 'I''m fascinated by this photo somehow!', '2008-02-13 23:54:30.000000', NULL, 1),
(4485510, 644622, 65319, '<td valign="top">The symmetry and colors are beautiful.</td>', 'The symmetry and colors are beautiful.', '2008-02-13 23:57:02.000000', NULL, 1),
(4485511, 645919, 65319, '<td valign="top">I''m fascinated by this photo!  I can''t wait to read the details.</td>', 'I''m fascinated by this photo!  I can''t wait to read the details.', '2008-02-13 23:58:20.000000', NULL, 1),
(4485513, 645845, 30456, '<td valign="top">Nice idea to alter the angle.  This really portrays the effect of speed.</td>', 'Nice idea to alter the angle.  This really portrays the effect of speed.', '2008-02-13 23:58:57.000000', NULL, 1),
(4485515, 646010, 30456, '<td valign="top">Great impressionistic effect here.  Wonderful how the face and whiskers are in full focus.</td>', 'Great impressionistic effect here.  Wonderful how the face and whiskers are in full focus.', '2008-02-13 23:59:53.000000', NULL, 1),
(4485517, 646470, 30456, '<td valign="top">Well done with just one cab in the shot.  Love the NYC background.</td>', 'Well done with just one cab in the shot.  Love the NYC background.', '2008-02-14 00:00:46.000000', NULL, 1),
(4485519, 645919, 30456, '<td valign="top">Interesting effect.</td>', 'Interesting effect.', '2008-02-14 00:01:07.000000', NULL, 1),
(4485521, 646040, 65319, '<td valign="top">Ahhhhh...hope to see this one on the front page!  Good Luck!!</td>', 'Ahhhhh...hope to see this one on the front page!  Good Luck!!', '2008-02-14 00:02:58.000000', NULL, 1),
(4485524, 646356, 65319, '<td valign="top">Ohhhhhh....beautiful!  The background is just spectacular against the white bird.</td>', 'Ohhhhhh....beautiful!  The background is just spectacular against the white bird.', '2008-02-14 00:04:51.000000', NULL, 1),
(4485525, 645427, 65319, '<td valign="top">Somehow I expect to see a mouse/rat running across the floor!  Happy New Year to you as well!</td>', 'Somehow I expect to see a mouse/rat running across the floor!  Happy New Year to you as well!', '2008-02-14 00:06:09.000000', NULL, 1),
(4485526, 646148, 65319, '<td valign="top">I like the ethereal almost zen quality of this photo.</td>', 'I like the ethereal almost zen quality of this photo.', '2008-02-14 00:07:24.000000', NULL, 1),
(4485530, 645437, 65319, '<td valign="top">Spirited away!  Beautiful photo and wonderful motion!</td>', 'Spirited away!  Beautiful photo and wonderful motion!', '2008-02-14 00:09:00.000000', NULL, 1),
(4485536, 646010, 65319, '<td valign="top">Wonderful motion and panning!  Too bad the tiger''s head wasn''t angled so we may see the eye!  Terrific capture.</td>', 'Wonderful motion and panning!  Too bad the tiger''s head wasn''t angled so we may see the eye!  Terrific capture.', '2008-02-14 00:11:07.000000', NULL, 1),
