(4486295, 646322, 66193, '<td valign="top">nice capture.  I would have liked you to have used a longer exposure time to give more motion in the background</td>', 'nice capture.  I would have liked you to have used a longer exposure time to give more motion in the background', '2008-02-14 11:18:07.000000', NULL, 1),
(4486300, 644248, 66193, '<td valign="top">i love the motion in the background.  looks like star trails!  doesn''t fit my strict definition of panning, but it is still a cool shot. gave it a 7 for the cool factor.</td>', 'i love the motion in the background.  looks like star trails!  doesn''t fit my strict definition of panning, but it is still a cool shot. gave it a 7 for the cool factor.', '2008-02-14 11:19:16.000000', NULL, 1),
(4486302, 645438, 66193, '<td valign="top">fits my definition of panning.  composition is quite static, though, since he''s right in the middle of the frame.  positioning him in the right side of the frame and riding into it would have made it more exciting.</td>', 'fits my definition of panning.  composition is quite static, though, since he''s right in the middle of the frame.  positioning him in the right side of the frame and riding into it would have made it more exciting.', '2008-02-14 11:20:10.000000', NULL, 1),
(4486305, 645964, 66193, '<td valign="top">nice motion is evident here.  good job.</td>', 'nice motion is evident here.  good job.', '2008-02-14 11:20:29.000000', NULL, 1),
(4486308, 646325, 66193, '<td valign="top">a looser crop would''ve helped convey some more motion.</td>', 'a looser crop would''ve helped convey some more motion.', '2008-02-14 11:20:57.000000', NULL, 1),
(4486313, 643268, 66193, '<td valign="top">how;d you get the veggies to be so sharp, while everything else is blurred. unless that is a different cart, and is stationary.</td>', 'how;d you get the veggies to be so sharp, while everything else is blurred. unless that is a different cart, and is stationary.', '2008-02-14 11:22:23.000000', NULL, 1),
(4486315, 644442, 66193, '<td valign="top">certainly fits the challenge.  the colors are not very exciting.</td>', 'certainly fits the challenge.  the colors are not very exciting.', '2008-02-14 11:22:54.000000', NULL, 1),
(4486317, 644374, 66193, '<td valign="top">nice capture.  this plane is certainly moving, and you indeed had to pan to catch this shot.  crop is a little tight for me, but nice shot overall.</td>', 'nice capture.  this plane is certainly moving, and you indeed had to pan to catch this shot.  crop is a little tight for me, but nice shot overall.', '2008-02-14 11:23:33.000000', NULL, 1),
(4486319, 645720, 66193, '<td valign="top">love the lines in this one.  the colors are great.  a little noisy, but a nice capture nonetheless.</td>', 'love the lines in this one.  the colors are great.  a little noisy, but a nice capture nonetheless.', '2008-02-14 11:24:00.000000', NULL, 1),
(4486321, 646131, 66193, '<td valign="top">the tilt is distracting to me.</td>', 'the tilt is distracting to me.', '2008-02-14 11:24:34.000000', NULL, 1),
(4486323, 646354, 66193, '<td valign="top">the lines from the bricks in the background are nice, and I get a sense of motion in this one.</td>', 'the lines from the bricks in the background are nice, and I get a sense of motion in this one.', '2008-02-14 11:25:03.000000', NULL, 1),
(4486324, 646267, 90203, '<td valign="top">This is such a cool panning idea. Nicely executed also.</td>', 'This is such a cool panning idea. Nicely executed also.', '2008-02-14 11:25:08.000000', NULL, 1),
(4486325, 646262, 66193, '<td valign="top">shutter speed was too fast.  there is no sense of motion here.  and there''s also a big glob of sensor dust there (should take care of that)</td>', 'shutter speed was too fast.  there is no sense of motion here.  and there''s also a big glob of sensor dust there (should take care of that)', '2008-02-14 11:25:39.000000', NULL, 1),
(4486326, 646291, 90203, '<td valign="top">I can''t really see the storm?</td>', 'I can''t really see the storm?', '2008-02-14 11:25:49.000000', NULL, 1),
(4486327, 644622, 90203, '<td valign="top">Not sure if this is panning.</td>', 'Not sure if this is panning.', '2008-02-14 11:26:05.000000', NULL, 1),
(4486328, 646336, 66193, '<td valign="top">nice creative use of panning.  the title does a good job of letting me know the context of the shot.  nice take on the challenge.</td>', 'nice creative use of panning.  the title does a good job of letting me know the context of the shot.  nice take on the challenge.', '2008-02-14 11:26:13.000000', NULL, 1),
(4486330, 646441, 90203, '<td valign="top">Love it! Nicely done in B&amp;W.</td>', 'Love it! Nicely done in B&W.', '2008-02-14 11:26:26.000000', NULL, 1),
(4486332, 643918, 66193, '<td valign="top">too much going on here for me.  parts of the white lion are blown out (at least on this monitor).</td>', 'too much going on here for me.  parts of the white lion are blown out (at least on this monitor).', '2008-02-14 11:26:54.000000', NULL, 1),
