(4486334, 644248, 90203, '<td valign="top">Cool idea! I wish the eyes are more in focus.</td>', 'Cool idea! I wish the eyes are more in focus.', '2008-02-14 11:27:19.000000', NULL, 1),
(4486335, 646356, 66193, '<td valign="top">wonderful selection of shutter speed.  I hope this was done legally, as I love the effect of the diagonal texture. 8.</td>', 'wonderful selection of shutter speed.  I hope this was done legally, as I love the effect of the diagonal texture. 8.', '2008-02-14 11:27:50.000000', NULL, 1),
(4486337, 646182, 90203, '<td valign="top">I would zoom in a little more. Very nicely done though!</td>', 'I would zoom in a little more. Very nicely done though!', '2008-02-14 11:28:14.000000', NULL, 1),
(4486338, 644741, 90203, '<td valign="top">The bright window in background bothers me a little. Cool idea though!</td>', 'The bright window in background bothers me a little. Cool idea though!', '2008-02-14 11:28:40.000000', NULL, 1),
(4486339, 646340, 66193, '<td valign="top">nice use of shutter speed and panning.  subject and what he/she is doing is kind of boring (although I''m sure the dog is a wonderful pet).</td>', 'nice use of shutter speed and panning.  subject and what he/she is doing is kind of boring (although I''m sure the dog is a wonderful pet).', '2008-02-14 11:28:54.000000', NULL, 1),
(4486341, 646336, 90203, '<td valign="top">Very creative. I wish the background is more simple.</td>', 'Very creative. I wish the background is more simple.', '2008-02-14 11:29:09.000000', NULL, 1),
(4486342, 645806, 66193, '<td valign="top">nice colors and great exposure control.  very good panning technique, too.</td>', 'nice colors and great exposure control.  very good panning technique, too.', '2008-02-14 11:29:27.000000', NULL, 1),
(4486343, 646131, 90203, '<td valign="top">Nicely done!!</td>', 'Nicely done!!', '2008-02-14 11:29:41.000000', NULL, 1),
(4486344, 645438, 90203, '<td valign="top">I know there is nothing you can do, but I wish the white line is not there.</td>', 'I know there is nothing you can do, but I wish the white line is not there.', '2008-02-14 11:30:04.000000', NULL, 1),
(4486346, 643642, 90203, '<td valign="top">Is this panning?</td>', 'Is this panning?', '2008-02-14 11:30:33.000000', NULL, 1),
(4486347, 644793, 66193, '<td valign="top">first pan I''ve seen in the challenge!  I like the creative use of props (I didn''t shoot for this challenge because I had no access to race cars or bicycle racers.  I did have a pan, though!)  The use of B&amp;W was a good choice, and you did a very nice job keeping the pan very sharp.</td>', 'first pan I''ve seen in the challenge!  I like the creative use of props (I didn''t shoot for this challenge because I had no access to race cars or bicycle racers.  I did have a pan, though!)  The use of B&W was a good choice, and you did a very nice job keeping the pan very sharp.', '2008-02-14 11:30:36.000000', NULL, 1),
(4486348, 646458, 90203, '<td valign="top">Too blurry for me..</td>', 'Too blurry for me..', '2008-02-14 11:30:46.000000', NULL, 1),
(4486351, 644179, 66193, '<td valign="top">putting the horses head off center would have made for a better composition</td>', 'putting the horses head off center would have made for a better composition', '2008-02-14 11:31:01.000000', NULL, 1),
(4486352, 645990, 90203, '<td valign="top">A little too blurry for me, otherwise I love it! The colors are great!</td>', 'A little too blurry for me, otherwise I love it! The colors are great!', '2008-02-14 11:31:15.000000', NULL, 1),
(4486354, 646025, 90203, '<td valign="top">Wow, nice! I love how sharp it is.</td>', 'Wow, nice! I love how sharp it is.', '2008-02-14 11:31:32.000000', NULL, 1),
(4486356, 644443, 90203, '<td valign="top">I love it! I like how sharp the eye is.</td>', 'I love it! I like how sharp the eye is.', '2008-02-14 11:31:50.000000', NULL, 1),
(4486358, 645491, 90203, '<td valign="top">Great capture of the moment!</td>', 'Great capture of the moment!', '2008-02-14 11:32:08.000000', NULL, 1);
