(4486626, 646354, 52549, '<td valign="top">Nice and clear. Good colours.</td>', 'Nice and clear. Good colours.', '2008-02-14 13:30:32.000000', NULL, 1),
(4486628, 645891, 52549, '<td valign="top">I think this is definitely top 3. Wonderful image.</td>', 'I think this is definitely top 3. Wonderful image.', '2008-02-14 13:32:24.000000', NULL, 1),
