(4488285, 646405, 66253, '<td valign="top">Nice with the incline in there</td>', 'Nice with the incline in there', '2008-02-15 07:49:10.000000', NULL, 1),
(4488286, 646356, 66253, '<td valign="top">good subject, nice texture</td>', 'good subject, nice texture', '2008-02-15 07:49:33.000000', NULL, 1),
(4488288, 646148, 66253, '<td valign="top">More abstract than I''d like to see, but a very nice idea</td>', 'More abstract than I''d like to see, but a very nice idea', '2008-02-15 07:50:09.000000', NULL, 1),
(4488292, 646298, 66253, '<td valign="top">Cool! Charming subject, nice contrast of sharpness and motion, and I like the composition.</td>', 'Cool! Charming subject, nice contrast of sharpness and motion, and I like the composition.', '2008-02-15 07:50:54.000000', NULL, 1),
(4488293, 644303, 66253, '<td valign="top">Love it!</td>', 'Love it!', '2008-02-15 07:51:14.000000', NULL, 1),
(4488294, 645491, 66253, '<td valign="top">Great composition and colors.</td>', 'Great composition and colors.', '2008-02-15 07:51:28.000000', NULL, 1),
(4488295, 646304, 66253, '<td valign="top">Oooh, interesting subject! (somehow I thought it was a bowling ball at first, but now I see)</td>', 'Oooh, interesting subject! (somehow I thought it was a bowling ball at first, but now I see)', '2008-02-15 07:52:28.000000', NULL, 1),
(4488297, 646029, 66253, '<td valign="top">Nice composition, colors, simplicity. I wish it were less noisy.</td>', 'Nice composition, colors, simplicity. I wish it were less noisy.', '2008-02-15 07:52:55.000000', NULL, 1),
(4488299, 645551, 66253, '<td valign="top">I''m holding onto my desk to keep from moving right forward into this. Very effective. Wow.</td>', 'I''m holding onto my desk to keep from moving right forward into this. Very effective. Wow.', '2008-02-15 07:53:55.000000', NULL, 1),
(4488300, 646459, 66253, '<td valign="top">What a cool looking bird! Nicely done; I wish we could see the feet, too.</td>', 'What a cool looking bird! Nicely done; I wish we could see the feet, too.', '2008-02-15 07:54:27.000000', NULL, 1),
(4488301, 644741, 66253, '<td valign="top">Cute subject. I''d like to see more panning motion; otherwise, it feels like it''s just blurry.</td>', 'Cute subject. I''d like to see more panning motion; otherwise, it feels like it''s just blurry.', '2008-02-15 07:55:43.000000', NULL, 1),
(4488304, 646262, 66253, '<td valign="top">What a great shape! I don''t feel the panning much, but I love the composition, contrast of colors.</td>', 'What a great shape! I don''t feel the panning much, but I love the composition, contrast of colors.', '2008-02-15 07:56:39.000000', NULL, 1),
(4488306, 645348, 66253, '<td valign="top">Great shot, nice composition, good colors, background is not too distracting, motion is really palpable, but most of all, their expressions are terrific!</td>', 'Great shot, nice composition, good colors, background is not too distracting, motion is really palpable, but most of all, their expressions are terrific!', '2008-02-15 07:58:36.000000', NULL, 1),
(4488309, 644179, 66253, '<td valign="top">Very nice. I wish there were a larger area in focus.</td>', 'Very nice. I wish there were a larger area in focus.', '2008-02-15 07:59:10.000000', NULL, 1),
(4488313, 646470, 66253, '<td valign="top">I think I''m gonna be sick! (that''s a compliment)</td>', 'I think I''m gonna be sick! (that''s a compliment)', '2008-02-15 07:59:57.000000', NULL, 1),
(4488314, 644660, 66253, '<td valign="top">This looks classic. Very nice.</td>', 'This looks classic. Very nice.', '2008-02-15 08:01:11.000000', NULL, 1),
(4488316, 643642, 66253, '<td valign="top">Interesting subject. I don''t see the panning.</td>', 'Interesting subject. I don''t see the panning.', '2008-02-15 08:01:34.000000', NULL, 1),
(4488317, 644698, 66253, '<td valign="top">Great title! I like the shot a lot, but can''t really tell that there''s panning going on.</td>', 'Great title! I like the shot a lot, but can''t really tell that there''s panning going on.', '2008-02-15 08:02:40.000000', NULL, 1),
(4488319, 644382, 66253, '<td valign="top">Love the subject. Oddly, I''d like to pull back a little farther and see what that looks like.</td>', 'Love the subject. Oddly, I''d like to pull back a little farther and see what that looks like.', '2008-02-15 08:03:18.000000', NULL, 1),
(4488320, 645778, 66253, '<td valign="top">Very nice.</td>', 'Very nice.', '2008-02-15 08:03:30.000000', NULL, 1),
(4488323, 646329, 66253, '<td valign="top">Marvelous.</td>', 'Marvelous.', '2008-02-15 08:04:03.000000', NULL, 1),
(4488327, 646010, 66253, '<td valign="top">Wow!</td>', 'Wow!', '2008-02-15 08:04:43.000000', NULL, 1),
(4488332, 646145, 66253, '<td valign="top">Beautiful abstract.</td>', 'Beautiful abstract.', '2008-02-15 08:05:35.000000', NULL, 1),
(4488338, 645720, 66253, '<td valign="top">Wow, very nice!</td>', 'Wow, very nice!', '2008-02-15 08:06:45.000000', NULL, 1),
(4488341, 646255, 66253, '<td valign="top">I love the contrast with the background.</td>', 'I love the contrast with the background.', '2008-02-15 08:07:53.000000', NULL, 1),
(4488342, 644363, 66253, '<td valign="top">Brilliant subject, and nicely done.</td>', 'Brilliant subject, and nicely done.', '2008-02-15 08:08:14.000000', NULL, 1),
(4488346, 646253, 66253, '<td valign="top">Love the composition, and your model is very arresting.</td>', 'Love the composition, and your model is very arresting.', '2008-02-15 08:09:14.000000', NULL, 1),
(4488348, 644622, 66253, '<td valign="top">Interesting, but it''s not clear to me what this is or how it''s panning.</td>', 'Interesting, but it''s not clear to me what this is or how it''s panning.', '2008-02-15 08:10:46.000000', NULL, 1),
(4488488, 646330, 83080, '<td valign="top">This is nice.  I love the tint in the car''s shadow.</td>', 'This is nice.  I love the tint in the car''s shadow.', '2008-02-15 09:51:35.000000', NULL, 1),
(4488494, 646360, 83080, '<td valign="top">Fantastic.  The motion is palpable.  Love the geometric shapes in this.</td>', 'Fantastic.  The motion is palpable.  Love the geometric shapes in this.', '2008-02-15 09:54:18.000000', NULL, 1),
(4488520, 644374, 83080, '<td valign="top">Wow, What a unique pov!  Is he banking with a hill in the background or are you in another plane looking down on him? (I''d guess banking)  The left wing feels slightly too close to the border for me, but hey, that reassures me that this isn''t just a model in front of a good blurry background ;)  Nice capture.</td>', 'Wow, What a unique pov!  Is he banking with a hill in the background or are you in another plane looking down on him? (I''d guess banking)  The left wing feels slightly too close to the border for me, but hey, that reassures me that this isn''t just a model in front of a good blurry background ;)  Nice capture.', '2008-02-15 10:05:53.000000', NULL, 1),
(4488529, 646336, 83080, '<td valign="top">Excellent concept.  If I had entered, I was thinking verticle myself.  Something along the lines of an egg down to a counter.  But that would take more skill and time than I currently possess.</td>', 'Excellent concept.  If I had entered, I was thinking verticle myself.  Something along the lines of an egg down to a counter.  But that would take more skill and time than I currently possess.', '2008-02-15 10:09:50.000000', NULL, 1),
(4488536, 646372, 83080, '<td valign="top">That''s an amazing feeling of motion while implying the verticle motion on either side of the shutter.</td>', 'That''s an amazing feeling of motion while implying the verticle motion on either side of the shutter.', '2008-02-15 10:13:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4488555, 644443, 83080, '<td valign="top">Great texture and sharpness.  I find my head is compensating for the tilt.  I do like the angles created and the strenght of the horizontal beak.</td>', 'Great texture and sharpness.  I find my head is compensating for the tilt.  I do like the angles created and the strenght of the horizontal beak.', '2008-02-15 10:22:59.000000', NULL, 1),
(4488558, 644660, 83080, '<td valign="top">Good sharp subject.  Nice motion blur.  This has a nice warm and happy feel to it.</td>', 'Good sharp subject.  Nice motion blur.  This has a nice warm and happy feel to it.', '2008-02-15 10:26:18.000000', NULL, 1),
(4488571, 645811, 83080, '<td valign="top">Great sharpness and background blur.  Good timing to get the line from the background through the rider.  A little tilt, but we''ll just call that downhill.</td>', 'Great sharpness and background blur.  Good timing to get the line from the background through the rider.  A little tilt, but we''ll just call that downhill.', '2008-02-15 10:31:03.000000', NULL, 1),
(4488573, 645806, 83080, '<td valign="top">The advertisers would love this sharpness.  I would love to see a shot like this from a perspective where I can see under the chassis.  Great capture.</td>', 'The advertisers would love this sharpness.  I would love to see a shot like this from a perspective where I can see under the chassis.  Great capture.', '2008-02-15 10:35:30.000000', NULL, 1),
(4488578, 645720, 83080, '<td valign="top">Isn''t this from the rule of thirds chapter?  Great sharpness, motion and composition.</td>', 'Isn''t this from the rule of thirds chapter?  Great sharpness, motion and composition.', '2008-02-15 10:38:49.000000', NULL, 1),
(4488590, 645375, 83080, '<td valign="top">Great lines and patterns.  It''s remarkable how everything has motion except for the foreground rider''s head.  Honestly, I didn''t apreciate how great this shot is on my first run through because I didn''t look close enough at that face (perhaps because it is darker than surroundings).  WOW!  Great shot!</td>', 'Great lines and patterns.  It''s remarkable how everything has motion except for the foreground rider''s head.  Honestly, I didn''t apreciate how great this shot is on my first run through because I didn''t look close enough at that face (perhaps because it is darker than surroundings).  WOW!  Great shot!', '2008-02-15 10:47:07.000000', NULL, 1),
(4488594, 645617, 83080, '<td valign="top">Great sharpness on the subject.</td>', 'Great sharpness on the subject.', '2008-02-15 10:50:55.000000', NULL, 1),
(4488595, 646260, 83080, '<td valign="top">Cool SP</td>', 'Cool SP', '2008-02-15 10:51:14.000000', NULL, 1),
(4488598, 646284, 83080, '<td valign="top">I like this shot and I think this technique is a smart way to pan.  Very effective.  The boy''s expression and hat spikes contrasting with the background really make this fun.</td>', 'I like this shot and I think this technique is a smart way to pan.  Very effective.  The boy''s expression and hat spikes contrasting with the background really make this fun.', '2008-02-15 10:55:29.000000', NULL, 1),
(4488599, 643637, 83080, '<td valign="top">Great idea.  For me, a little more dof might be nice, but that might be really difficult since you probably had to be quite close.  Hope you didn''t scratch the record.</td>', 'Great idea.  For me, a little more dof might be nice, but that might be really difficult since you probably had to be quite close.  Hope you didn''t scratch the record.', '2008-02-15 10:55:34.000000', NULL, 1),
(4488600, 646267, 83080, '<td valign="top">Nice capture and nice job keeping her face in focus.  This is the most ''drawing like'' effect I''ve seen in these panning entries.</td>', 'Nice capture and nice job keeping her face in focus.  This is the most ''drawing like'' effect I''ve seen in these panning entries.', '2008-02-15 10:55:40.000000', NULL, 1),
(4488608, 645672, 83080, '<td valign="top">Nice motion and subject sharpness.  It seems like you used a longer exposure than some of the other horse shots which really accentuates the speed here.</td>', 'Nice motion and subject sharpness.  It seems like you used a longer exposure than some of the other horse shots which really accentuates the speed here.', '2008-02-15 10:59:40.000000', NULL, 1),
(4488609, 645449, 83080, '<td valign="top">Nice lines and I love the varied background texture.</td>', 'Nice lines and I love the varied background texture.', '2008-02-15 11:00:04.000000', NULL, 1),
(4488610, 646423, 83080, '<td valign="top">This gives me the impression of a static shot with very creamy bokeh.  Disconnecting the rider from anything moving and without an obvious motion blur in the background, it gives my mind just a little difficulty reconciling the overall composition (and that might just be my feeble mind :)  I like the angles &amp; lines throughout.</td>', 'This gives me the impression of a static shot with very creamy bokeh.  Disconnecting the rider from anything moving and without an obvious motion blur in the background, it gives my mind just a little difficulty reconciling the overall composition (and that might just be my feeble mind :)  I like the angles & lines throughout.', '2008-02-15 11:00:08.000000', NULL, 1),
(4488612, 644248, 83080, '<td valign="top">lol!  What a fun idea!  I would love to see a shot of getting this shot.</td>', 'lol!  What a fun idea!  I would love to see a shot of getting this shot.', '2008-02-15 11:00:15.000000', NULL, 1),
(4488614, 646232, 83080, '<td valign="top">Love the clean lines, the wheel blur, and that I can see the driver''s face.  Nice shot.</td>', 'Love the clean lines, the wheel blur, and that I can see the driver''s face.  Nice shot.', '2008-02-15 11:02:22.000000', NULL, 1),
(4488615, 646354, 83080, '<td valign="top">I love the lines on this one.  Great choice of background.</td>', 'I love the lines on this one.  Great choice of background.', '2008-02-15 11:02:35.000000', NULL, 1),
(4488619, 646031, 83080, '<td valign="top">This is a pretty shot.  Great lines &amp; lighting.  The shutter speed is a little fast for me as the motion blur is very subtle for a panning challenge (could almost be mistaken for strong bokeh).  Still, this deserves high marks overall.</td>', 'This is a pretty shot.  Great lines & lighting.  The shutter speed is a little fast for me as the motion blur is very subtle for a panning challenge (could almost be mistaken for strong bokeh).  Still, this deserves high marks overall.', '2008-02-15 11:08:22.000000', NULL, 1),
(4488620, 646329, 83080, '<td valign="top">Wow.  Vivid colors.  I like the composition.  Lines on the plane are very jagged.  Nice shot.</td>', 'Wow.  Vivid colors.  I like the composition.  Lines on the plane are very jagged.  Nice shot.', '2008-02-15 11:10:03.000000', NULL, 1),
(4488621, 646032, 83080, '<td valign="top">Great job keeping the driver in focus.  It really draws my eyes right to her.</td>', 'Great job keeping the driver in focus.  It really draws my eyes right to her.', '2008-02-15 11:10:08.000000', NULL, 1),
(4488632, 646025, 83080, '<td valign="top">Fun capture.  There are some jagged lines that are distracting.  The colors are very strong.</td>', 'Fun capture.  There are some jagged lines that are distracting.  The colors are very strong.', '2008-02-15 11:21:36.000000', NULL, 1),
(4488677, 646124, 89431, '<td valign="top">I like all the vertical lines that created a repeated pattern throughout the picture, but it almost makes it appear she is standing and almost stops the movement. Horizontal lines would have created more of a flow.</td>', 'I like all the vertical lines that created a repeated pattern throughout the picture, but it almost makes it appear she is standing and almost stops the movement. Horizontal lines would have created more of a flow.', '2008-02-15 11:53:09.000000', NULL, 1),
(4488690, 645391, 89431, '<td valign="top">Usually one thing should be in complete focus with panning but i like the idea and all the vibrant colors in the merry-go-round.</td>', 'Usually one thing should be in complete focus with panning but i like the idea and all the vibrant colors in the merry-go-round.', '2008-02-15 11:57:38.000000', NULL, 1),
(4488698, 646031, 89431, '<td valign="top">The values and contrast in this photograph are beautiful.</td>', 'The values and contrast in this photograph are beautiful.', '2008-02-15 12:10:44.000000', NULL, 1),
(4488723, 644340, 83080, '<td valign="top">Adorable.  The brightest lights are distracting to me, but the overall effect is very fun.</td>', 'Adorable.  The brightest lights are distracting to me, but the overall effect is very fun.', '2008-02-15 12:30:06.000000', NULL, 1),
(4488724, 646131, 83080, '<td valign="top">Excellent sharpness &amp; color on the car, but for me the background is close to being just blurry rather than being motion blurred, so I have an unsettling double vision feeling.  I really love looking at this car with the crowd blocked to include only the top third of the frame (although I''m sure this will do better as you have it cropped).  I like the way the tilt flattens out some of the car lines while creating some interesting angles.</td>', 'Excellent sharpness & color on the car, but for me the background is close to being just blurry rather than being motion blurred, so I have an unsettling double vision feeling.  I really love looking at this car with the crowd blocked to include only the top third of the frame (although I''m sure this will do better as you have it cropped).  I like the way the tilt flattens out some of the car lines while creating some interesting angles.', '2008-02-15 12:30:12.000000', NULL, 1),
(4488726, 644791, 83080, '<td valign="top">Nice shot.  The head seems a bit overexposed but you tracked the bird nicely and the feel of motion is great.</td>', 'Nice shot.  The head seems a bit overexposed but you tracked the bird nicely and the feel of motion is great.', '2008-02-15 12:31:45.000000', NULL, 1),
(4488729, 645348, 83080, '<td valign="top">That''s funny!  Each boy has such a dramatically different expression.  Great isolation of their faces and feel of motion.</td>', 'That''s funny!  Each boy has such a dramatically different expression.  Great isolation of their faces and feel of motion.', '2008-02-15 12:33:24.000000', NULL, 1),
(4488735, 644089, 83080, '<td valign="top">nice motion.  Great idea catcing the spray of water in front of the headlight.</td>', 'nice motion.  Great idea catcing the spray of water in front of the headlight.', '2008-02-15 12:34:39.000000', NULL, 1),
(4488739, 644382, 83080, '<td valign="top">Nice composition.  The motion blur is a little too subtle for me, but the way rowers move probably makes them one of the more difficult subjects to catch at the longer speeds.</td>', 'Nice composition.  The motion blur is a little too subtle for me, but the way rowers move probably makes them one of the more difficult subjects to catch at the longer speeds.', '2008-02-15 12:38:28.000000', NULL, 1),
(4488745, 645491, 83080, '<td valign="top">Great subject clarity and fell of motion. The background lines are a little jagged in places which is slightly distracting for me, but high marks for the overall composition and effect.</td>', 'Great subject clarity and fell of motion. The background lines are a little jagged in places which is slightly distracting for me, but high marks for the overall composition and effect.', '2008-02-15 12:43:49.000000', NULL, 1),
(4488749, 646129, 83080, '<td valign="top">Nice clear subject and great wheel motion.  A slightly longer shutter might have given a stronger overall sense of motion, but it''s clearly panning.</td>', 'Nice clear subject and great wheel motion.  A slightly longer shutter might have given a stronger overall sense of motion, but it''s clearly panning.', '2008-02-15 12:46:14.000000', NULL, 1),
(4488751, 645817, 83080, '<td valign="top">Pretty horse.  My initial impression was to see this as a static head shot with some shake because the head is so prominent and mostly sharp.  The background and mane give away the motion, but my eyes are having difficulty reconciling the overall compostion.  It does make for an intersting perspective compared to the other gallop pictures.</td>', 'Pretty horse.  My initial impression was to see this as a static head shot with some shake because the head is so prominent and mostly sharp.  The background and mane give away the motion, but my eyes are having difficulty reconciling the overall compostion.  It does make for an intersting perspective compared to the other gallop pictures.', '2008-02-15 12:46:18.000000', NULL, 1),
(4488753, 644303, 6667, '<td valign="top">Super capture. Love the smiles.  BOL</td>', 'Super capture. Love the smiles.  BOL', '2008-02-15 12:46:29.000000', NULL, 1),
(4488764, 645906, 83080, '<td valign="top">LOL!  Great concept.  The light on the counter is distracting and the colors are a little off to me.  The arm in particular has a funny hue but I''ll go with the reddish victim as intentional.  Perhaps that''s all part of the insane killer perspective!  :P  Nice shot (I mean stab).</td>', 'LOL!  Great concept.  The light on the counter is distracting and the colors are a little off to me.  The arm in particular has a funny hue but I''ll go with the reddish victim as intentional.  Perhaps that''s all part of the insane killer perspective!  :P  Nice shot (I mean stab).', '2008-02-15 12:51:42.000000', NULL, 1),
(4488774, 645700, 83080, '<td valign="top">LOL!  Nice SP!  Now if you had gone further around with your head off to one side I''d <i>really </i>be impressed.</td>', 'LOL!  Nice SP!  Now if you had gone further around with your head off to one side I''d really be impressed.', '2008-02-15 12:57:43.000000', NULL, 1),
(4488775, 644741, 6667, '<td valign="top">After seeing the image of the African Crowned Crane, I came back to bump this image up.  There is somewhat of a resemblance!!!   BOL</td>', 'After seeing the image of the African Crowned Crane, I came back to bump this image up.  There is somewhat of a resemblance!!!   BOL', '2008-02-15 12:58:04.000000', NULL, 1),
(4488781, 645720, 6667, '<td valign="top">Nice play on the title.  Had an opportunity to ride a bullet. . . just like flying low!!!  Very nice capture. BOL</td>', 'Nice play on the title.  Had an opportunity to ride a bullet. . . just like flying low!!!  Very nice capture. BOL', '2008-02-15 13:00:17.000000', NULL, 1),
(4488784, 644301, 83080, '<td valign="top">Ha ha.  It feels like the tilt of the camera is accentuating the centrifugal tilt of the car.</td>', 'Ha ha.  It feels like the tilt of the camera is accentuating the centrifugal tilt of the car.', '2008-02-15 13:01:35.000000', NULL, 1),
(4488787, 646010, 83080, '<td valign="top">That''s haunting.  Great job keeping the head sharp.  I can hardly wait to see what your settings were for this.</td>', 'That''s haunting.  Great job keeping the head sharp.  I can hardly wait to see what your settings were for this.', '2008-02-15 13:03:01.000000', NULL, 1),
(4488792, 645845, 6667, '<td valign="top">Love the "feeling" of this shot.  But the trees take it away.  Nicely done.  BOL</td>', 'Love the "feeling" of this shot.  But the trees take it away.  Nicely done.  BOL', '2008-02-15 13:05:28.000000', NULL, 1),
(4488832, 646145, 83080, '<td valign="top">Whoah!  I love astrophysics, but I am having difficulty following this motion.  I love the metalic texture of the blur and the lines certainly are interesting to follow.  When I cover the two strongest rectangular lights it really lets my eyes relax and enjoy the shapes.  Very interesting.</td>', 'Whoah!  I love astrophysics, but I am having difficulty following this motion.  I love the metalic texture of the blur and the lines certainly are interesting to follow.  When I cover the two strongest rectangular lights it really lets my eyes relax and enjoy the shapes.  Very interesting.', '2008-02-15 13:20:00.000000', NULL, 1),
(4488839, 643812, 83080, '<td valign="top">That''s some strange background blur with the clock.  The candle feels too close to the edge for me.  Great sharpness of the candle &amp; base.</td>', 'That''s some strange background blur with the clock.  The candle feels too close to the edge for me.  Great sharpness of the candle & base.', '2008-02-15 13:27:11.000000', NULL, 1),
(4488848, 644363, 83080, '<td valign="top">Ha ha!  I can see the wheels are level, but the horizontal gate lines are so strong with their slight right tilt that it gives me an off balance feeling.  This shot is just ripe for creative captions.  You could do a creative captions thread with it after the voting.  :P</td>', 'Ha ha!  I can see the wheels are level, but the horizontal gate lines are so strong with their slight right tilt that it gives me an off balance feeling.  This shot is just ripe for creative captions.  You could do a creative captions thread with it after the voting.  :P', '2008-02-15 13:34:45.000000', NULL, 1),
(4488850, 646177, 83080, '<td valign="top">Love the lines and the color. Nice job keeping the subject sharp.</td>', 'Love the lines and the color. Nice job keeping the subject sharp.', '2008-02-15 13:36:06.000000', NULL, 1),
(4488854, 644463, 83080, '<td valign="top">Hard to get a good panning angle on these guys I''ll bet.  Nice job getting a motion feel.  The subject lacks sharpness, but I think this shot has a higher degree of difficulty than most.</td>', 'Hard to get a good panning angle on these guys I''ll bet.  Nice job getting a motion feel.  The subject lacks sharpness, but I think this shot has a higher degree of difficulty than most.', '2008-02-15 13:38:09.000000', NULL, 1),
(4488863, 645778, 83080, '<td valign="top">Nice sharp subject and good background &amp; wheel motion.  Not sure how I feel about the tilt yet, if the buildings weren''t in the background I might like it more.  Colors are great.</td>', 'Nice sharp subject and good background & wheel motion.  Not sure how I feel about the tilt yet, if the buildings weren''t in the background I might like it more.  Colors are great.', '2008-02-15 13:43:16.000000', NULL, 1),
(4488870, 646040, 83080, '<td valign="top">Beautiful shot.  The shutter had to be pretty fast to stop those wings and, unfortunately, it stopped the background too so I don''t get a panning feel from it.  Still, high marks for a really nice looking shot.</td>', 'Beautiful shot.  The shutter had to be pretty fast to stop those wings and, unfortunately, it stopped the background too so I don''t get a panning feel from it.  Still, high marks for a really nice looking shot.', '2008-02-15 13:50:25.000000', NULL, 1),
(4488871, 644793, 83080, '<td valign="top">Well, I knew someone would do a play on words and I''m just glad it wasn''t a pan being used as a weapon.  Cute shot.</td>', 'Well, I knew someone would do a play on words and I''m just glad it wasn''t a pan being used as a weapon.  Cute shot.', '2008-02-15 13:52:00.000000', NULL, 1),
(4488875, 645438, 83080, '<td valign="top">Nice shot.  The front of the bike is very sharp.  Too bad he had to move his head.</td>', 'Nice shot.  The front of the bike is very sharp.  Too bad he had to move his head.', '2008-02-15 13:53:43.000000', NULL, 1),
