(4499765, 646329, 28742, '<td valign="top">Congrats, Jason!<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Achooooo:</b></div><hr/><i>The great thing about this shot is if you zoom in, the pilot is looking straight at me. </i></td></tr></table> <br/>Hey, <a href="//www.dpchallenge.com/image.php?IMAGE_ID=649095" rel="nofollow" target="_blank">you''re right</a>!</td>', 'Congrats, Jason! Originally posted by Achooooo:The great thing about this shot is if you zoom in, the pilot is looking straight at me.  Hey, you''re right!', '2008-02-20 01:30:26.000000', NULL, 0),
(4499766, 645720, 68504, '<td valign="top">Nice simple lines lines and sweet contrast between metallic train, including windows and subdued colours of countryside.  (Yeah, liked title too).</td>', 'Nice simple lines lines and sweet contrast between metallic train, including windows and subdued colours of countryside.  (Yeah, liked title too).', '2008-02-20 01:31:26.000000', NULL, 0),
